class OfflineCodec<T> {
  const OfflineCodec({
    required this.table,
    required this.key,
    required this.columns,
    required this.localColumns,
    required this.fromLocal,
    required this.fromRemote,
    required this.toLocal,
    required this.toRemote,
  });
  final String table;
  final String key;
  final Map<String, String> columns;
  final Map<String, String> localColumns;
  final T Function(Map<String, dynamic>) fromLocal;
  final T Function(Map<String, dynamic>) fromRemote;
  final Map<String, dynamic> Function(T) toLocal;
  final Map<String, dynamic> Function(T) toRemote;
  Object decodeLocal(Map<String, dynamic> row) => fromLocal(row) as Object;
  Object decodeRemote(Map<String, dynamic> row) => fromRemote(row) as Object;
  Map<String, dynamic> encodeLocal(Object model) => toLocal(model as T);
  Map<String, dynamic> encodeRemote(Object model) => toRemote(model as T);
  Type get modelType => T;
  String get localTable => T.toString();
  String get localKey => localColumns.entries
      .firstWhere((entry) => columns[entry.key] == key)
      .value;
}

final memojiModelCodec = OfflineCodec<MemojiModel>(
