  localColumns: {'name': 'name', 'link': 'link', 'sexe': 'sexe', 'mid': 'mid'},
  fromLocal: (r) => MemojiModel(
    name: (r['name'] as String? ?? ''),
    link: (r['link'] as String? ?? ''),
    sexe: (r['sexe'] as String? ?? ''),
    mid: (r['mid'] as String?),
  ),
  fromRemote: (r) => MemojiModel(
    name: (r['name'] as String? ?? ''),
    link: (r['link'] as String? ?? ''),
    sexe: (r['sexe'] as String? ?? ''),
    mid: (r['mid'] as String?),
  ),
  toLocal: (m) => {
    'name': m.name,
    'link': m.link,
    'sexe': m.sexe,
    'mid': m.mid,
  },
  toRemote: (m) => {
